const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const safeRead=(key,fallback)=>{try{const value=JSON.parse(localStorage.getItem(key));return value??fallback}catch{return fallback}};
const safeSave=(key,value)=>{try{localStorage.setItem(key,JSON.stringify(value));return true}catch{return false}};
const desktop=$('#desktop'),windows=$('#windows'),openWindows=new Map();let topZ=20,activeId=null,soundOn=safeRead('guptios-sounds',false),bootDone=false,toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.add('hidden'),3500)}
function clickSound(){if(!soundOn)return;try{const c=new AudioContext(),o=c.createOscillator(),g=c.createGain();o.type='sine';o.frequency.setValueAtTime(700,c.currentTime);o.frequency.exponentialRampToValueAtTime(420,c.currentTime+.05);g.gain.setValueAtTime(.03,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+.07);o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+.08);o.onended=()=>c.close()}catch{}}
function setSound(enabled){soundOn=enabled;safeSave('guptios-sounds',enabled);$('#sound-button').innerHTML=icon(enabled?'speaker':'muted');$('#sound-button').title='Interface sounds: '+(enabled?'on':'off');$('#sound-button').setAttribute('aria-label',enabled?'Mute interface sounds':'Enable interface sounds');const c=$('#sound-setting');if(c)c.checked=enabled}
function folderPage(id,subtitle){return `<div class="folder-toolbar"><label>Address</label><div class="address">${icon('folder')}C:\\GuptiOS\\${apps[id].name}</div></div><div class="explorer"><aside class="explorer-side">${icon(apps[id].icon)}<h2>${apps[id].name}</h2><p>${subtitle}</p><p>0 items</p></aside><div class="folder-empty">${icon('folder')}<h2>This folder is ready for its first story.</h2><p>We’re getting things in order.<br>Check back for ${id==='projects'?'projects and experiments':id==='experience'?'experience and milestones':'achievements and highlights'}.</p></div></div>`}
const content={
 bookshelf:()=>`<article class="shelf-page"><header class="shelf-header"><div class="eyebrow">Off the clock / Personal favourites</div><h1>The bookshelf</h1><p>Five books I keep coming back to.</p></header><section id="shelf-books"><div class="shelf-section-title"><h2>The bookshelf</h2><span>MY TOP FIVE</span></div><div class="shelf-grid"><article class="shelf-card"><div class="shelf-art"><img src="covers/meditations.jpg" alt="Meditations cover" loading="lazy"></div><div class="shelf-card-text"><span class="shelf-rank">01</span><h3>Meditations</h3><p>Marcus Aurelius</p><blockquote class="shelf-quote">“Waste no more time arguing about what a good man should be. Be one.”</blockquote></div></article><article class="shelf-card"><div class="shelf-art"><img src="covers/show-your-work.jpg" alt="Show Your Work! cover" loading="lazy"></div><div class="shelf-card-text"><span class="shelf-rank">02</span><h3>Show Your Work!</h3><p>Austin Kleon</p><blockquote class="shelf-quote">“You can’t find your voice if you don’t use it.”</blockquote></div></article><article class="shelf-card"><div class="shelf-art"><img src="covers/meaning.jpg" alt="Man’s Search for Meaning cover" loading="lazy"></div><div class="shelf-card-text"><span class="shelf-rank">03</span><h3>Man’s Search for Meaning</h3><p>Viktor E. Frankl</p><blockquote class="shelf-quote">“When we are no longer able to change a situation … we are challenged to change ourselves.”</blockquote></div></article><article class="shelf-card"><div class="shelf-art"><img src="covers/friends.jpg" alt="How to Win Friends and Influence People cover" loading="lazy"></div><div class="shelf-card-text"><span class="shelf-rank">04</span><h3>How to Win Friends and Influence People</h3><p>Dale Carnegie</p><blockquote class="shelf-quote">“Abilities wither under criticism; they blossom under encouragement.”</blockquote></div></article><article class="shelf-card"><div class="shelf-art"><img src="covers/deep-work.jpg" alt="Deep Work cover" loading="lazy"></div><div class="shelf-card-text"><span class="shelf-rank">05</span><h3>Deep Work</h3><p>Cal Newport</p><blockquote class="shelf-quote">“Clarity about what matters provides clarity about what does not.”</blockquote></div></article></div></section><footer class="shelf-footer">A personal collection · Cover artwork belongs to its respective owners.</footer></article>`,
 gaming:()=>`<article class="shelf-page"><header class="shelf-header"><div class="eyebrow">Off the clock / Personal favourites</div><h1>Gaming</h1><p>Favourite worlds, stories, and save files.</p></header><section id="shelf-games"><div class="shelf-section-title"><h2>Save files worth keeping</h2><span>MY TOP FIVE PICKS</span></div><div class="shelf-grid games-grid"><article class="shelf-card"><div class="shelf-art"><img src="covers/resident-evil.jpg" alt="Resident Evil series cover" loading="lazy"></div><div class="shelf-card-text"><span class="shelf-rank">01</span><h3>Resident Evil series</h3><p>Favourites: 2, 4, 8 & 9</p></div></article><article class="shelf-card"><div class="shelf-art"><img src="covers/batman.jpg" alt="Batman: Arkham series cover" loading="lazy"></div><div class="shelf-card-text"><span class="shelf-rank">02</span><h3>Batman: Arkham series</h3><p>Favourite: Arkham Knight</p></div></article><article class="shelf-card"><div class="shelf-art"><img src="covers/wukong.jpg" alt="Black Myth: Wukong cover" loading="lazy"></div><div class="shelf-card-text"><span class="shelf-rank">03</span><h3>Black Myth: Wukong</h3><p></p></div></article><article class="shelf-card"><div class="shelf-art"><img src="covers/walking-dead.jpg" alt="The Walking Dead cover" loading="lazy"></div><div class="shelf-card-text"><span class="shelf-rank">04</span><h3>The Walking Dead</h3><p>The Telltale series</p></div></article><article class="shelf-card"><div class="shelf-art"><img src="covers/detroit.jpg" alt="Detroit: Become Human cover" loading="lazy"></div><div class="shelf-card-text"><span class="shelf-rank">05</span><h3>Detroit: Become Human</h3><p>Joint fifth pick</p></div></article><article class="shelf-card"><div class="shelf-art"><img src="covers/wolf.jpg" alt="The Wolf Among Us cover" loading="lazy"></div><div class="shelf-card-text"><span class="shelf-rank">05</span><h3>The Wolf Among Us</h3><p>Joint fifth pick</p></div></article></div></section><footer class="shelf-footer">A personal collection · Cover artwork belongs to its respective owners.</footer></article>`,
 welcome:()=>`<div class="welcome-layout"><aside class="welcome-side">${icon('computer')}<div class="side-label">YOU ARE EXPLORING<b>GuptiOS</b>Personal Edition<br>Version 1.0</div></aside><div class="welcome-main"><div class="eyebrow">Shresth Gupta / Personal desktop</div><h1>Welcome to<br>my <em>desktop.</em></h1><p>Computer Science + Business at KAIST.<br>A space for my work, ideas, and everything I’m exploring along the way.</p><p>Pick a folder. Open a window.<br>Make yourself at home.</p><div class="welcome-actions"><button class="bevel button primary" data-open="about">Start exploring →</button><button class="bevel button" data-open="readme">Take a quick tour</button></div><div class="welcome-footnote">${icon('folder')} Always a work in progress.</div></div></div>`,
 about:()=>`<article class="profile"><header class="profile-header"><figure class="profile-photo"><img src="profile.jpg" alt="Shresth Gupta standing under an umbrella on a rainy night" width="1152" height="1536"><figcaption>GUPTI / PERSONAL FILE</figcaption></figure><div><div class="eyebrow">The person behind the desktop</div><h1>Shresth Gupta</h1><p class="profile-degree">Computer Science + Business at KAIST</p><span class="profile-scholar">Full-ride scholar · Daejeon, South Korea</span></div></header><section class="profile-story"><p>I’m drawn to problems that bring code, numbers, and business together. My main interests are quantitative finance and entrepreneurship, with computer science at the centre of both.</p><p>I’ve built projects in machine learning and data analysis, and worked on investment analysis and technology policy research. I like getting into the details, whether that means understanding a dataset, an algorithm, or the thinking behind a business decision.</p></section><section class="profile-outside"><h2>When I’m away from the keyboard</h2><p>There’s guitar, gaming, a book to get through, and travelling whenever I get the chance. I like having something new to explore, on a screen or somewhere I haven’t been before.</p><div class="profile-interests"><span>Guitar</span><button class="interest-travel" data-open="bookshelf">Bookshelf ↗</button><button class="interest-travel" data-open="gaming">Gaming ↗</button><button class="interest-travel" data-open="travel">Travelling ↗</button></div></section><figure class="profile-motto"><figcaption>A PERSONAL REMINDER</figcaption><blockquote>“If you wanna win and succeed in life then your commitment to your future must be greater than your attachment to your life”</blockquote></figure><footer class="profile-footer"><span>Shresth, also known as Gupti.</span><button class="bevel button" data-open="projects">Explore my projects →</button></footer></article>`,
 projects:()=>`<div class="folder-toolbar"><label>Address</label><div class="address">${icon('folder')}C:\\GuptiOS\\Projects</div></div><article class="projects-page"><header class="projects-heading"><div><div class="eyebrow">Selected work / 01—04</div><h1>Built out of curiosity.</h1><p>Machine learning, early websites, and small experiments.</p></div>${icon('folder')}</header><section class="project-entry featured-project"><div class="project-index">01 / MACHINE LEARNING</div><h2>Reading handwritten digits</h2><p>A PyTorch neural network that classifies MNIST digits. The notebook brings together image preprocessing, model training, per-digit evaluation, and prediction visualisation.</p><div class="project-tags"><span>Python</span><span>PyTorch</span><span>MNIST</span></div><div class="project-detail">Under the hood: a fully connected network with dropout and Adam optimisation.</div><a class="bevel button" href="https://github.com/WiseShrestha/MNIST_Project" target="_blank" rel="noopener noreferrer">Explore the notebook ↗</a></section><section class="project-entry"><div class="project-index">02 / WEB DEVELOPMENT</div><h2>The original 8-bit website</h2><p>An early HTML and CSS website, kept in my GitHub Pages repository. A little piece of where my interest in building for the web began.</p><div class="project-tags"><span>HTML</span><span>CSS</span><span>2021</span></div><a class="project-link" href="https://github.com/WiseShrestha/WiseShrestha.github.io/tree/main/8_bit_website" target="_blank" rel="noopener noreferrer">View source ↗</a></section><section class="project-entry"><div class="project-index">03 / PYTHON EXPERIMENT</div><h2>Hot or cold?</h2><p>A command-line number guessing game with hot-and-cold hints. A small exercise in loops, conditionals, and random numbers.</p><div class="project-tags"><span>Python</span><span>Command line</span></div><a class="project-link" href="https://github.com/WiseShrestha/Calculator-Demo-Project" target="_blank" rel="noopener noreferrer">View source ↗</a></section><section class="project-entry"><div class="project-index">04 / OPEN SOURCE</div><h2>devup-ui: Korean Team page</h2><p>Added a Korean translation of the Team page, updated page metadata and language alternatives, and registered the translated route while reusing the existing layout.</p><div class="project-tags"><span>Documentation</span><span>Localisation</span><span>PR submitted</span></div><a class="project-link" href="https://github.com/dev-five-git/devup-ui/pull/889" target="_blank" rel="noopener noreferrer">View pull request #889 ↗</a></section><footer class="projects-footer"><span>More experiments, as they happen.</span><a href="https://github.com/WiseShrestha?tab=repositories" target="_blank" rel="noopener noreferrer">All repositories ↗</a></footer></article>`,
 goaPhoto:()=>`<figure class="travel-photo-view"><img src="goa.png" alt="A beach in Goa at night, with waves and lights along the horizon"><figcaption>Goa, India<br><span class="photo-memory">Late-night drives with friends.</span></figcaption></figure>`,
 chennaiPhoto:()=>`<figure class="travel-photo-view"><img src="chennai.png" alt="Waves on a Chennai beach beneath a cloud-filled sky"><figcaption>Chennai, India<br><span class="photo-memory">Summer school at IIT Madras.</span></figcaption></figure>`,
 seoulPhoto:()=>`<figure class="travel-photo-view"><img src="seoul.png" alt="Nighttime river scene in Seoul, with an illuminated bridge, skyline and people along the waterfront"><figcaption>Seoul, South Korea<br><span class="photo-memory">Banpo Bridge Fountain Show.</span></figcaption></figure>`,
 travel:()=>`<article class="travel-page"><header class="travel-heading"><div class="eyebrow">Away from the keyboard / Travel collection</div><h1>A few places along the way.</h1><p>Goa, Chennai, and Seoul. Three stops from my travels.</p></header><div class="travel-cards">${[{name:'Goa',memory:'Late-night drives with friends.',country:'India',code:'GOA',tone:'sand',photo:'goa.png',viewer:'goaPhoto',alt:'A beach in Goa at night, with waves and lights along the horizon'},{name:'Chennai',memory:'Summer school at IIT Madras.',country:'India',code:'MAA',tone:'sea',photo:'chennai.png',viewer:'chennaiPhoto',alt:'Waves on a Chennai beach beneath a cloud-filled sky'},{name:'Seoul',memory:'Banpo Bridge Fountain Show.',country:'South Korea',code:'SEL',tone:'rose',photo:'seoul.png',viewer:'seoulPhoto',alt:'Seoul at night: an illuminated bridge and city lights across the river'}].map((place,i)=>`<section class="travel-card ${place.tone}"><div class="postcard-top"><span>PERSONAL COLLECTION</span><span>0${i+1}</span></div>${place.photo ? `<button class="travel-cover" data-open="${place.viewer}" aria-label="Open ${place.name} photo"><img src="${place.photo}" alt="${place.alt}"><span>View photo ↗</span></button>` : `<div class="travel-stamp" aria-hidden="true">${icon('globe')}<span>${place.code}</span></div>`}<h2>${place.name}</h2><p>${place.country}</p><p class="travel-memory">${place.memory}</p><div class="postcard-rule"></div><span class="travel-visited">VISITED</span></section>`).join('')}</div><footer class="travel-footer"><span>${icon('document')} A growing collection of places and moments.</span><span>GUPTIOS / OUT OF OFFICE</span></footer></article>`,
 experience:()=>`<article class="career-page"><div class="eyebrow">Finance / Research / Leadership</div><h1>Learning through the work.</h1><p class="career-intro">Across investment research, technology policy, and community organisations.</p><section class="career-entry"><div class="eyebrow">Apr 2025–Present</div><h2>Investment Analyst</h2><b class="career-org">Brooklyn Youth Charitable Investment Group</b><p>Reviewed equity proposals and startup portfolios, contributing financial-analysis and impact-investment perspectives to investment recommendations.</p></section><section class="career-entry"><div class="eyebrow">Apr–Aug 2025</div><h2>Student Researcher</h2><b class="career-org">Indo-Pacific Studies Center</b><p>Supported research on technology, economics, and diplomacy; analysed and visualised regional trade patterns and contributed to work on India’s digital economic policy framework.</p></section><section class="career-entry"><div class="eyebrow">Dec 2024–May 2025</div><h2>Young Innovator Intern</h2><b class="career-org">Scaler School of Technology</b><p>Explored AI-powered personal branding tools, neural networks, prompt engineering, and product design with industry mentorship.</p></section><section class="career-entry"><div class="eyebrow">2024–Present</div><h2>Student Researcher</h2><b class="career-org">New York Academy of Sciences</b><p>Collaborated on SDG-focused research on marine and land pollution, sustainable food systems, and biodiversity, using community research and data visualisation.</p></section><section class="career-entry"><div class="eyebrow">2020–Present</div><h2>Digital Media & Chapter Leadership</h2><b class="career-org">Tale of Humankind</b><p>Former Chief Growth Officer and team member, contributing to digital outreach, web development, design, and events. Part of the organising team for Metamorphosis 2026 in collaboration with IIT Delhi’s Academic Outreach & New Initiatives.</p></section><section class="career-entry"><div class="eyebrow">2024–Present</div><h2>Creative & Chapter Leadership</h2><b class="career-org">Dublieu · Project Surya</b><p>Head of Video Editing at Dublieu and Executive Chapter Head / Graphic Designer at Project Surya, with work spanning video production, volunteer coordination, recruitment, and chapter activities.</p></section></article>`,
 achievements:()=>`<article class="career-page"><div class="eyebrow">Selected milestones</div><h1>A few things I’m proud of.</h1><div class="awards-grid"><section class="award-card"><div class="eyebrow">01 / MATHEMATICS</div><h2>Country #1 · Global #3</h2><p>American Mathematics Olympiad · 2024</p></section><section class="award-card"><div class="eyebrow">02 / EDUCATION</div><h2>KAIST full-ride scholar</h2><p>Computer Science undergraduate · 2026–2030</p></section><section class="award-card"><div class="eyebrow">03 / ACADEMICS</div><h2>AP Scholar with Distinction</h2><p>Calculus AB: 5 · Microeconomics: 5 · Chemistry, Physics 1, Macroeconomics: 4</p></section><section class="award-card"><div class="eyebrow">04 / OLYMPIADS</div><h2>Gold medals</h2><p>Fermat Mathematical Olympiad, National Junior Cybersecurity Olympiad, and International Mathematics Olympiad Competition of Southeast Asia · 2025. National Astronomy and Science Olympiad · Levels 1 & 2.</p></section><section class="award-card"><div class="eyebrow">05 / SCIENCE & MATHEMATICS</div><h2>Across disciplines</h2><p>Diamond: Asiarope Science Olympiad. Silver: Asiarope Mathematics Olympiad. Bronze: Singapore and Asian Schools Math Olympiad and Singapore Math Global Finals · 2025.</p></section><section class="award-card"><div class="eyebrow">06 / INNOVATION</div><h2>Youth Ideathon finalist</h2><p>Top 1,000 · 2023 & 2024</p></section><section class="award-card"><div class="eyebrow">07 / ASTRONOMY</div><h2>State rank #6</h2><p>National Astronomy and Science Olympiad · 2024</p></section></div><section class="publication"><div class="eyebrow">Research publication / October 2024</div><h2>Enhancing Access And Communication: The Impact Of Chatbots On Underserved Communities</h2><p>Sole-author paper · International Journal of Engineering Development and Research · Volume 12, Issue 4.</p></section></article>`,
 resume:()=>`<article class="content-pad"><div class="eyebrow">Personal documents / PDF</div><h1>The short version.</h1><p>My education, projects, research, and experience in one place.</p><div class="file-preview">${icon('document')}<div><b>Shresth_Gupta_Resume.pdf</b><span class="muted small">One-page résumé · PDF document</span></div></div><div class="welcome-actions"><a class="bevel button primary" href="resume.pdf" target="_blank" rel="noopener">Open résumé ↗</a><a class="bevel button" href="resume.pdf" download="Shresth_Gupta_Resume.pdf">Download PDF ↓</a></div><p class="muted small">Computer Science + Business at KAIST · Daejeon, South Korea</p></article>`,
 contact:()=>`<div class="content-pad contact-page"><div class="eyebrow">Inbox / New connections</div><h1>Say hello.</h1><p>Have an idea, a project, or something interesting to share? I’d love to hear from you.</p><div class="contact-email">${icon('mail')}<div><span class="contact-label">EMAIL</span><a href="mailto:shresth.gupta@kaist.ac.kr">shresth.gupta@kaist.ac.kr</a></div></div><div class="contact-actions"><a class="bevel button" href="mailto:shresth.gupta@kaist.ac.kr">Write an email →</a><button class="bevel button" id="copy-email">Copy email</button><span id="copy-email-status" role="status"></span></div><div class="contact-socials"><a href="https://www.linkedin.com/in/shresth-gupta-5173202a1/" target="_blank" rel="noopener noreferrer"><span><b>LinkedIn</b><small>Experience, updates, and connections</small></span><span aria-hidden="true">↗</span></a><a href="https://github.com/WiseShrestha" target="_blank" rel="noopener noreferrer"><span><b>GitHub</b><small>WiseShrestha · Code and projects</small></span><span aria-hidden="true">↗</span></a></div><p class="contact-signoff">Shresth Gupta · KAIST</p></div>`,
 thoughts:()=>`<div class="notepad-shell"><textarea id="notepad" aria-label="Your scratchpad" spellcheck="false"></textarea><div class="note-info" id="note-status">Scratchpad · Saved only in this browser. Use File → Save text file to download your notes.</div></div>`,
 readme:()=>`<div class="content-pad"><div class="eyebrow">READ ME.TXT</div><h1>A few things to know.</h1><p>You’ve found a portfolio that works like an old computer. Here’s your quick tour.</p><ol class="readme-list"><li><span class="number">01</span><div><b>Follow your curiosity.</b><p>Click any desktop icon, or use Start to find an app.</p></div></li><li><span class="number">02</span><div><b>Make room for your windows.</b><p>Drag a title bar to move a window. Use the corner to resize, or the top-right buttons to minimize, maximize, and close.</p></div></li><li><span class="number">03</span><div><b>There’s more on the desktop.</b><p>Try the ambient music player, change the wallpaper, or type <span class="key">help</span> in the MS-DOS Prompt.</p></div></li></ol><p class="muted small">Tip: double-click a title bar to maximize. Press <span class="key">Esc</span> to dismiss menus.</p><button class="bevel button" data-open="settings">Make it yours</button></div>`,
 settings:()=>`<div class="settings-body"><div class="tabs"><span class="tab">Background</span></div><div class="tab-panel"><div class="monitor-preview"><div class="monitor-case"><div class="monitor-screen" id="monitor-screen"></div></div><div class="monitor-neck"></div><div class="monitor-base"></div></div><label>Wallpaper</label><div class="wall-options">${['Meadow','Classic teal','After hours'].map((v,i)=>`<button class="bevel wall-option" data-theme="${['meadow','teal','night'][i]}" aria-pressed="false">${v}</button>`).join('')}</div><div class="settings-row"><label for="fit-setting">Picture display</label><select id="fit-setting"><option value="cover">Fill screen</option><option value="contain">Fit picture</option></select></div><label class="checkbox-row"><input type="checkbox" id="sound-setting"> Play interface sounds</label><p class="settings-foot">Changes apply immediately and are remembered in this browser.</p></div></div>`,
 guestbook:()=>`<div class="content-pad"><div class="eyebrow">The guestbook</div><h1>You were here.</h1><div class="guest-notice">Preview guestbook: notes stay in this browser. They aren’t sent or visible to other visitors.</div><form id="guest-form" class="guest-form"><label for="guest-name">Your name</label><input class="text-input" id="guest-name" name="name" maxlength="50" placeholder="A fellow explorer" required><label for="guest-note">A little note</label><textarea class="text-input" id="guest-note" name="message" maxlength="500" placeholder="Something kind. Something curious." required></textarea><button class="bevel button" type="submit">Leave a local note</button></form><div id="guest-notes"></div></div>`,
 terminal:()=>`<div class="terminal"><div class="terminal-header">GuptiOS [Version 1.0]<br>Personal Edition. All curiosity welcome.<br><br>Type HELP for a list of commands.</div><div id="terminal-output" aria-live="polite"></div><form id="terminal-form"><label for="terminal-input">C:\\GUPTI&gt;</label><input id="terminal-input" autocomplete="off" autocapitalize="off" spellcheck="false" aria-label="Command"></form></div>`,
 music:()=>`<div class="media-body"><div class="media-display" id="media-display"><small>GUPTI’S FAVOURITE SONG</small><div class="media-title">Softcore</div><small>THE NEIGHBOURHOOD</small><div class="equalizer" aria-hidden="true">${Array.from({length:24},(_,i)=>`<i style="--i:${i};--h:${25+(i*37)%75}%"></i>`).join('')}</div></div><div class="media-controls"><button class="bevel" id="music-play" aria-label="Play Softcore">▶</button><button class="bevel" id="music-stop" aria-label="Stop Softcore">■</button><span class="small" id="music-state">Stopped</span><time id="music-time">00:00</time></div><label class="seek-row">Track position <input id="music-seek" type="range" min="0" max="100" value="0" step="0.1" aria-label="Track position"></label><label class="volume-row">Volume <input id="music-volume" type="range" min="0" max="100" value="30" aria-label="Music volume"></label><p class="media-description">The Neighbourhood — Softcore.<br>Press play, open a folder, and stay a while.</p></div>`,
 shutdown:()=>`<div class="shutdown-body">${icon('computer')}<b>What would you like to do?</b><p>Restart the desktop to return to the beginning.<br>Your saved notes and preferences will stay here.</p><div class="shutdown-actions"><button class="bevel button" id="restart">Restart</button><button class="bevel button" data-close="shutdown">Cancel</button></div></div>`
};
function focusWindow(id){const state=openWindows.get(id);if(!state)return;state.minimized=false;state.el.classList.remove('hidden');state.el.style.zIndex=++topZ;activeId=id;openWindows.forEach((s,k)=>s.el.classList.toggle('inactive',k!==id));renderTasks()}
function focusNext(){const visible=[...openWindows.entries()].filter(([,s])=>!s.minimized).sort((a,b)=>Number(b[1].el.style.zIndex)-Number(a[1].el.style.zIndex));activeId=null;if(visible.length)focusWindow(visible[0][0]);else renderTasks()}
function minimizeWindow(id){const s=openWindows.get(id);if(!s)return;s.minimized=true;s.el.classList.add('hidden');if(activeId===id)focusNext();else renderTasks()}
function closeWindow(id){const s=openWindows.get(id);if(!s)return;if(id==='music')stopMusic();s.el.remove();openWindows.delete(id);focusNext();const shortcut=$(`[data-shortcut="${id}"]`);if(!activeId&&shortcut)shortcut.focus({preventScroll:true})}
function maximizeWindow(id){const s=openWindows.get(id);if(!s)return;s.maximized=!s.maximized;s.el.classList.toggle('maximized',s.maximized);const b=s.el.querySelector('[data-control="maximize"]');b.setAttribute('aria-label',(s.maximized?'Restore ':'Maximize ')+apps[id].name);b.title=s.maximized?'Restore':'Maximize';focusWindow(id)}
function renderTasks(){const container=$('#task-buttons');container.replaceChildren();openWindows.forEach((s,id)=>{const b=document.createElement('button');b.className='bevel task-button'+(activeId===id&&!s.minimized?' active':'');b.innerHTML=icon(apps[id].icon)+`<span>${apps[id].name}</span>`;b.title=apps[id].name;b.setAttribute('aria-label',`${s.minimized?'Restore':'Switch to'} ${apps[id].name}`);b.onclick=()=>{clickSound();if(activeId===id&&!s.minimized)minimizeWindow(id);else focusWindow(id)};container.append(b)});container.querySelector('.active')?.scrollIntoView({block:'nearest',inline:'nearest'})}
function openApp(id){if(!apps[id])return;hidePopups();clickSound();if(openWindows.has(id)){focusWindow(id);return}const a=apps[id],el=document.createElement('section');el.className='window bevel';el.dataset.app=id;el.setAttribute('role','region');el.setAttribute('aria-label',a.name+' window');const count=openWindows.size,w=Math.min(a.width,innerWidth-12),h=Math.min(a.height,innerHeight-70);let x=Math.max(190,Math.round(innerWidth*.23)),y=Math.max(45,Math.round(innerHeight*.19));if(id!=='welcome'){x+=(count%5)*24;y+=(count%5)*19}x=Math.max(4,Math.min(x,innerWidth-w-18));y=Math.max(4,Math.min(y,innerHeight-h-50));Object.assign(el.style,{left:x+'px',top:y+'px',width:w+'px',height:h+'px'});
 el.innerHTML=`<header class="titlebar">${icon(a.icon)}<span class="window-title">${a.name}${id==='thoughts'?'':id==='welcome'?' to GuptiOS':''}</span><div class="window-controls"><button class="bevel window-control" data-control="minimize" aria-label="Minimize ${a.name}" title="Minimize"><i class="control-min"></i></button><button class="bevel window-control" data-control="maximize" aria-label="Maximize ${a.name}" title="Maximize"><i class="control-max"></i></button><button class="bevel window-control close" data-control="close" aria-label="Close ${a.name}" title="Close"><span class="control-close">×</span></button></div></header><nav class="menubar" aria-label="${a.name} menu"><button data-menu="file"><u>F</u>ile</button><button data-menu="view"><u>V</u>iew</button><button data-menu="help"><u>H</u>elp</button></nav><div class="window-body">${content[id]()}</div><footer class="window-status"><span>${a.status||(['projects','experience','achievements'].includes(id)?'0 items':id==='thoughts'?'Saved locally':'GuptiOS · Personal Edition')}</span><span>${id==='welcome'?'Explore at your pace':'Ready'}</span></footer><div class="resize-handle" aria-hidden="true"></div>`;
 windows.append(el);const state={el,minimized:false,maximized:false};openWindows.set(id,state);el.addEventListener('pointerdown',()=>{if(activeId!==id)focusWindow(id)});el.querySelectorAll('[data-control]').forEach(b=>b.onclick=()=>{clickSound();({minimize:minimizeWindow,maximize:maximizeWindow,close:closeWindow})[b.dataset.control](id)});el.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openApp(b.dataset.open));el.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>closeWindow(b.dataset.close));el.querySelectorAll('[data-menu]').forEach(b=>b.onclick=e=>windowMenu(e,id,b.dataset.menu));setupDrag(id);setupResize(id);focusWindow(id);initializeApp(id);}
function setupDrag(id){const s=openWindows.get(id),bar=s.el.querySelector('.titlebar');bar.ondblclick=e=>{if(!e.target.closest('button'))maximizeWindow(id)};bar.onpointerdown=e=>{if(e.target.closest('button')||s.maximized||innerWidth<=600)return;const rect=s.el.getBoundingClientRect(),dx=e.clientX-rect.left,dy=e.clientY-rect.top;bar.setPointerCapture(e.pointerId);bar.onpointermove=ev=>{s.el.style.left=Math.max(0,Math.min(innerWidth-s.el.offsetWidth,ev.clientX-dx))+'px';s.el.style.top=Math.max(0,Math.min(innerHeight-70,ev.clientY-dy))+'px'};const end=()=>{bar.onpointermove=null};bar.onpointerup=end;bar.onpointercancel=end;bar.onlostpointercapture=end}}
function setupResize(id){const s=openWindows.get(id),handle=s.el.querySelector('.resize-handle');handle.onpointerdown=e=>{e.preventDefault();const rect=s.el.getBoundingClientRect();handle.setPointerCapture(e.pointerId);handle.onpointermove=ev=>{s.el.style.width=Math.max(310,Math.min(innerWidth-rect.left-4,ev.clientX-rect.left))+'px';s.el.style.height=Math.max(220,Math.min(innerHeight-rect.top-42,ev.clientY-rect.top))+'px'};const end=()=>handle.onpointermove=null;handle.onpointerup=end;handle.onpointercancel=end;handle.onlostpointercapture=end}}
function hidePopups(){['start-menu','context-menu','calendar','window-menu'].forEach(id=>document.getElementById(id)?.classList.add('hidden'));$('#start-button').setAttribute('aria-expanded','false');$('#start-button').classList.remove('pressed');$('#clock-button').setAttribute('aria-expanded','false')}
function toggleStart(){const show=$('#start-menu').classList.contains('hidden');hidePopups();if(show){$('#start-menu').classList.remove('hidden');$('#start-button').setAttribute('aria-expanded','true');$('#start-button').classList.add('pressed');$('#start-menu button').focus()}}
function windowMenu(e,id,type){const current=$('#window-menu');const same=current&&!current.classList.contains('hidden')&&current.dataset.owner===id&&current.dataset.type===type;hidePopups();if(same)return;let menu=current;if(!menu){menu=document.createElement('div');menu.id='window-menu';menu.className='popup bevel';desktop.append(menu)}menu.dataset.owner=id;menu.dataset.type=type;menu.replaceChildren();const choices=type==='file'?(id==='thoughts'?[['Save text file',downloadNotes],['Close',()=>closeWindow(id)]]:[['Close',()=>closeWindow(id)]]):type==='view'?[['Maximize / Restore',()=>maximizeWindow(id)],['Minimize',()=>minimizeWindow(id)],['Display properties',()=>openApp('settings')]]:[['How to use GuptiOS',()=>openApp('readme')],['About this desktop',()=>openApp('welcome')]];choices.forEach(([text,fn])=>{const b=document.createElement('button');b.textContent=text;b.onclick=()=>{hidePopups();fn()};menu.append(b)});const r=e.currentTarget.getBoundingClientRect();menu.style.left=Math.min(r.left,innerWidth-180)+'px';menu.style.top=r.bottom+'px';menu.classList.remove('hidden')}
function downloadNotes(){const text=$('#notepad')?.value??safeRead('guptios-notepad','');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'text/plain'}));a.download='GuptiOS-notes.txt';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function initializeApp(id){if(id==='bookshelf'||id==='gaming'){setupShelf(id)}if(id==='contact'){$('#copy-email').onclick=async()=>{const status=$('#copy-email-status');try{if(!navigator.clipboard?.writeText)throw new Error('Clipboard unavailable');await navigator.clipboard.writeText('shresth.gupta@kaist.ac.kr');status.textContent='Copied!'}catch{status.textContent='Select the email above to copy it.'}}}if(id==='thoughts'){const area=$('#notepad');area.value=safeRead('guptios-notepad','A thought starts here.\n\nThis is your little scratchpad.\nWrite something, leave, come back. It will still be here.\n\n— Saved in this browser only.');area.oninput=()=>{const ok=safeSave('guptios-notepad',area.value);$('#note-status').textContent=ok?'Saved locally · '+area.value.length+' characters · This browser only.':'Storage unavailable · Use File → Save text file to keep your notes.'}}
 if(id==='settings'){syncSettings();$('#fit-setting').onchange=e=>{safeSave('guptios-fit',e.target.value);applyTheme()};$('#sound-setting').onchange=e=>{setSound(e.target.checked);clickSound()};$$('[data-theme]').forEach(b=>b.onclick=()=>{safeSave('guptios-theme',b.dataset.theme);applyTheme();syncSettings()})}
 if(id==='guestbook'){renderGuestNotes();$('#guest-form').onsubmit=e=>{e.preventDefault();const name=$('#guest-name').value.trim(),message=$('#guest-note').value.trim();if(!name||!message){toast('Please add your name and a note.');return}const entries=safeRead('guptios-guestbook-v2',[]);entries.unshift({name,message,date:new Date().toISOString()});if(!safeSave('guptios-guestbook-v2',entries.slice(0,40))){toast('Browser storage is unavailable. Your note could not be saved.');return}e.target.reset();renderGuestNotes();toast('Your note is saved in this browser.')}}
 if(id==='terminal')setupTerminal();if(id==='music'){const stored=Number(safeRead('guptios-volume',30));$('#music-volume').value=Number.isFinite(stored)?Math.max(0,Math.min(100,stored)):30;$('#music-play').onclick=toggleMusic;$('#music-stop').onclick=stopMusic;$('#music-seek').oninput=e=>{if(Number.isFinite(song.duration))song.currentTime=Number(e.target.value)/100*song.duration};updateMusicUI();$('#music-volume').oninput=e=>{safeSave('guptios-volume',Number(e.target.value));song.volume=Number(e.target.value)/100}}
 if(id==='shutdown')$('#restart').onclick=()=>{[...openWindows.keys()].forEach(closeWindow);hidePopups();runBoot()};}

function setupShelf(collectionId){
 const cards=[...openWindows.get(collectionId).el.querySelectorAll('.shelf-card')];
 cards.forEach(card=>{const art=card.querySelector('.shelf-art'),img=art.querySelector('img'),title=card.querySelector('h3').textContent;
 const button=document.createElement('button');button.type='button';button.className='shelf-cover-button';button.setAttribute('aria-label','View '+title);img.replaceWith(button);button.append(img);
 button.onclick=()=>{const id='collectionViewer';if(openWindows.has(id))closeWindow(id);
 apps[id]={name:title,icon:'book',width:620,height:650,status:'Personal collection · Cover viewer'};
 content[id]=()=>`<article class="collection-view"><button class="bevel button" data-back-shelf>← Back to collection</button><img src="${img.getAttribute('src')}" alt="${img.alt}"><div class="eyebrow">PERSONAL FAVOURITE</div><h1>${title}</h1><p>${card.querySelector('.shelf-card-text>p').textContent}</p>${card.querySelector('blockquote')?.outerHTML||''}</article>`;
 openApp(id);openWindows.get(id).el.querySelector('[data-back-shelf]').onclick=()=>{closeWindow(id);openApp(collectionId);if(button.isConnected)button.focus({preventScroll:true})};};
 });
}

function renderGuestNotes(){const container=$('#guest-notes');container.replaceChildren();const entries=safeRead('guptios-guestbook-v2',[]);if(!Array.isArray(entries))return;entries.forEach(n=>{const div=document.createElement('div');div.className='guest-entry';const b=document.createElement('b'),p=document.createElement('p'),t=document.createElement('time');b.textContent=n.name;p.textContent=n.message;t.textContent=new Date(n.date).toLocaleDateString();div.append(b,t,p);container.append(div)})}
function setupTerminal(){const form=$('#terminal-form'),input=$('#terminal-input'),output=$('#terminal-output');let history=[],cursor=0;const print=text=>{const div=document.createElement('div');div.className='terminal-line';div.textContent=text;output.append(div)};form.onsubmit=e=>{e.preventDefault();const raw=input.value.trim(),cmd=raw.toLowerCase();input.value='';if(!raw)return;history.push(raw);cursor=history.length;print('C:\\GUPTI> '+raw);const aliases={about:'about',projects:'projects',bookshelf:'bookshelf',gaming:'gaming',travel:'travel',experience:'experience',achievements:'achievements',resume:'resume',notepad:'thoughts',thoughts:'thoughts',contact:'contact',music:'music',settings:'settings',readme:'readme'};if(cmd==='help')print('HELP        Show this list\nDIR         List desktop folders\nABOUT       Open About Me\nPROJECTS    Open Projects\nNOTEPAD     Open your local scratchpad\nMUSIC       Open Media Player\nSETTINGS    Change the wallpaper\nDATE        Show date and time\nVER         Show OS version\nCLS         Clear this screen\nEXIT        Close this window');else if(cmd==='dir')print(Object.keys(aliases).map(x=>'<DIR>  '+x.toUpperCase()).join('\n'));else if(cmd==='cls'||cmd==='clear')output.replaceChildren();else if(cmd==='date')print(new Date().toLocaleString());else if(cmd==='ver')print('GuptiOS 1.0 — Personal Edition');else if(cmd==='whoami')print('A curious visitor. Make yourself at home.');else if(cmd==='exit'){closeWindow('terminal');return}else if(aliases[cmd]){print('Opening '+apps[aliases[cmd]].name+'…');openApp(aliases[cmd])}else print('Unknown command. Type HELP to see what’s available.');input.scrollIntoView({block:'nearest'})};input.onkeydown=e=>{if(e.key==='ArrowUp'){e.preventDefault();cursor=Math.max(0,cursor-1);input.value=history[cursor]||''}if(e.key==='ArrowDown'){e.preventDefault();cursor=Math.min(history.length,cursor+1);input.value=history[cursor]||''}};input.focus({preventScroll:true})}
function applyTheme(){const theme=safeRead('guptios-theme','meadow'),fit=safeRead('guptios-fit','cover');desktop.style.backgroundImage=theme==='teal'?'none':theme==='night'?'radial-gradient(ellipse at 65% 70%,#384551,#172330 70%)':"url('wallpaper.png')";desktop.style.backgroundColor=theme==='night'?'#172330':'#008080';desktop.style.backgroundSize=fit==='contain'?'contain':'cover';const monitor=$('#monitor-screen');if(monitor){monitor.style.backgroundImage=desktop.style.backgroundImage;monitor.style.backgroundColor=desktop.style.backgroundColor}}
function syncSettings(){const theme=safeRead('guptios-theme','meadow');$$('[data-theme]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.theme===theme)));$('#fit-setting').value=safeRead('guptios-fit','cover');$('#sound-setting').checked=soundOn;applyTheme()}
let musicPlaying=false,musicSeconds=0;
const song=new Audio('softcore.mp3');song.preload='metadata';
song.addEventListener('timeupdate',()=>{musicSeconds=Math.floor(song.currentTime);updateMusicUI()});
song.addEventListener('loadedmetadata',updateMusicUI);
song.addEventListener('ended',()=>{musicPlaying=false;updateMusicUI()});
song.addEventListener('error',()=>{musicPlaying=false;updateMusicUI();toast('The song could not load. Please try again.')});
async function toggleMusic(){try{if(!song.paused){song.pause();musicPlaying=false}else{song.volume=Number($('#music-volume')?.value??30)/100;await song.play();musicPlaying=true}updateMusicUI()}catch{toast('Press play to start the song in your browser.')}}
function updateMusicUI(){if(!$('#music-play'))return;$('#music-play').textContent=musicPlaying?'Ⅱ':'▶';$('#music-play').setAttribute('aria-label',musicPlaying?'Pause Softcore':'Play Softcore');$('#media-display').classList.toggle('playing',musicPlaying);$('#music-state').textContent=musicPlaying?'Playing':musicSeconds?'Paused':'Stopped';const seek=$('#music-seek');if(seek){seek.disabled=!Number.isFinite(song.duration);seek.value=Number.isFinite(song.duration)?song.currentTime/song.duration*100:0}$('#music-time').textContent=String(Math.floor(musicSeconds/60)).padStart(2,'0')+':'+String(musicSeconds%60).padStart(2,'0')}
function stopMusic(){song.pause();song.currentTime=0;musicPlaying=false;musicSeconds=0;updateMusicUI()}
function showCalendar(){const show=$('#calendar').classList.contains('hidden');hidePopups();if(!show)return;const now=new Date(),first=new Date(now.getFullYear(),now.getMonth(),1).getDay(),days=new Date(now.getFullYear(),now.getMonth()+1,0).getDate();$('#calendar').innerHTML=`<h3>${now.toLocaleDateString(undefined,{month:'long',year:'numeric'})}</h3><div class="calendar-grid">${['S','M','T','W','T','F','S'].map(d=>`<b>${d}</b>`).join('')}${'<span></span>'.repeat(first)}${Array.from({length:days},(_,i)=>`<span class="${i+1===now.getDate()?'today':''}">${i+1}</span>`).join('')}</div><footer>${Intl.DateTimeFormat().resolvedOptions().timeZone.replaceAll('_',' ')}</footer>`;$('#calendar').classList.remove('hidden');$('#clock-button').setAttribute('aria-expanded','true')}
function clock(){const now=new Date();$('#clock').textContent=now.toLocaleTimeString(undefined,{hour:'numeric',minute:'2-digit'});$('#clock-button').title=now.toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric',year:'numeric'})}clock();setInterval(clock,1000);
function runBoot(){bootDone=false;$('#boot').style.opacity='1';$('#boot').classList.remove('hidden');const progress=$('.boot-progress i');progress.style.animation='none';void progress.offsetWidth;progress.style.animation='';$('#boot-status').textContent='Starting your desktop…';setTimeout(()=>{if(!bootDone)$('#boot-status').textContent='Everything is right where you left it.'},700);setTimeout(finishBoot,1550)}
function finishBoot(){if(bootDone)return;bootDone=true;$('#boot').style.opacity='0';setTimeout(()=>$('#boot').classList.add('hidden'),250);openApp('welcome')}
for(const id of desktopApps){const b=document.createElement('button');b.className='shortcut';b.dataset.shortcut=id;b.innerHTML=icon(apps[id].icon)+`<span class="shortcut-label">${apps[id].name==='MS-DOS Prompt'?'Terminal':apps[id].name}</span>`;b.onclick=()=>{$$('.shortcut').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');openApp(id)};$('#shortcuts').append(b)}
const startIds=['welcome','about','projects','experience','achievements','resume','contact','travel','bookshelf','gaming','thoughts','music','terminal','settings','readme','shutdown'];for(const id of startIds){if(id==='settings'||id==='shutdown')$('#start-items').append(document.createElement('hr'));const b=document.createElement('button');b.className='menu-item';b.innerHTML=icon(apps[id].icon)+`<span>${id==='shutdown'?'Shut Down…':apps[id].name}</span>`;b.onclick=()=>openApp(id);$('#start-items').append(b)}
$('#start-icon').innerHTML=icon('logo');$('#boot-logo').innerHTML=icon('logo');$('#show-desktop').innerHTML=icon('computer');$('#start-button').onclick=toggleStart;$('#clock-button').onclick=showCalendar;$('#sound-button').onclick=()=>{setSound(!soundOn);clickSound()};$('#skip-boot').onclick=finishBoot;
let hiddenByDesktop=[];$('#show-desktop').onclick=()=>{const visible=[...openWindows].filter(([,s])=>!s.minimized).map(([id])=>id);if(visible.length){hiddenByDesktop=visible;visible.forEach(minimizeWindow)}else{hiddenByDesktop.forEach(id=>focusWindow(id));hiddenByDesktop=[]}};
document.addEventListener('pointerdown',e=>{if(!e.target.closest('.popup,.start-menu,#start-button,#clock-button,.calendar,.menubar'))hidePopups();if(e.target===desktop||e.target.classList.contains('wallpaper-vignette'))$$('.shortcut').forEach(b=>b.classList.remove('selected'))});
desktop.addEventListener('contextmenu',e=>{if(e.target.closest('.window,.taskbar,.start-menu,.popup'))return;e.preventDefault();hidePopups();const menu=$('#context-menu');menu.classList.remove('hidden');menu.style.left=Math.min(e.clientX,innerWidth-175)+'px';menu.style.top=Math.min(e.clientY,innerHeight-165)+'px'});
$$('#context-menu [data-action]').forEach(b=>b.onclick=()=>{hidePopups();if(b.dataset.action==='settings')openApp('settings');else if(b.dataset.action==='refresh'){applyTheme();clock();toast('Desktop refreshed.')}else toast('Icons are arranged by category.')});
document.addEventListener('keydown',e=>{if(!bootDone&&(e.key==='Enter'||e.key==='Escape')){e.preventDefault();finishBoot();return}if(e.key==='Escape')hidePopups();if(e.altKey&&e.key==='F4'&&activeId){e.preventDefault();closeWindow(activeId)}if(e.ctrlKey&&e.key==='Escape'){e.preventDefault();toggleStart()}const menu=e.target.closest('.start-menu,.popup');if(menu&&['ArrowDown','ArrowUp','Home','End'].includes(e.key)){e.preventDefault();const buttons=[...menu.querySelectorAll('button')],idx=buttons.indexOf(document.activeElement),next=e.key==='Home'?0:e.key==='End'?buttons.length-1:(idx+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length;buttons[next]?.focus()}});
window.addEventListener('resize',()=>{openWindows.forEach(s=>{if(s.maximized||innerWidth<=600)return;const r=s.el.getBoundingClientRect();s.el.style.left=Math.max(0,Math.min(r.left,innerWidth-s.el.offsetWidth))+'px';s.el.style.top=Math.max(0,Math.min(r.top,innerHeight-90))+'px'})});
setSound(soundOn);applyTheme();runBoot();
